(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w2 = Math.sin(x*0.035-t*0.15)*8+Math.cos(y*0.028+t*0.18)*6;
  const w3 = Math.cos((x+y)*0.012+t*0.22)*12;
  const sx = x+w1+w2, sy = y+w1*0.7+w2+w3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*45, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.5;
  }
  const act=aS/7.1, inh=iS/7.1, coupler=cS/7.1;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin((sx+sy)*0.12+t*2.5)+Math.sin((sx-sy)*0.1-t*2))/2;
  const bg3=Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*0.6)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08-ang*5+t*0.9)*0.2;
  const lap = ((aS>0?1:-1)*0.3 + bg*0.2 + bg2*0.15 + spiral + spiral2 + bg3);
  const rd1 = Math.tanh((act - inh*0.7 + coupler*0.3 + lap)*2.0);
  const fine = Math.sin(sx*0.25+Math.sin(sy*0.2+t)*2)*Math.sin(sy*0.25+Math.cos(sx*0.18-t)*2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+fine*0.3)*1.5)*0.3;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.1*Math.abs(rd1);
  const edge = 1.0 - Math.min(1, Math.abs(rd1 - Math.tanh((act*0.95 - inh*0.72 + coupler*0.25 + lap)*2.0))*8);
  const blend = rd1*0.6 + cell*0.2 + micro*0.05 + edge*0.15;
  const v = blend*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[12,65,120],[18,110,130],[30,155,135],[120,175,100],[210,190,65],[220,145,55],[195,85,60],[150,45,70],[90,20,65],[40,12,55],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.75+Math.sin(rd1*Math.PI)*0.25;
  const glow=Math.max(0, 1-Math.abs(rd1)*2.5)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum+glow*100)|0)
  ];
}
